import { ChakraProvider, defaultSystem } from "@chakra-ui/react";
import { render, screen } from "@testing-library/react";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { initInspectorStore, inspectorStore } from "./store";
import { Inspector } from "./Inspector";

const mockUseBotConnection = vi.fn();

vi.mock("./hooks/useBotConnection", () => ({
  useBotConnection: (...args: unknown[]) => mockUseBotConnection(...args) as void,
}));

const mockUseTrackerConnection = vi.fn();
vi.mock("./hooks/useTrackerConnection", () => ({
  useTrackerConnection: (...args: unknown[]) => mockUseTrackerConnection(...args) as void,
}));

vi.mock("./hooks/useConversationData", () => ({
  useConversationData: vi.fn(),
}));

vi.mock("./try-assistant/TryAssistant", () => ({
  TryAssistant: () => <div data-testid="try-assistant" />,
}));

vi.mock("uuid", () => ({
  v4: () => "generated-uuid",
}));

// ChakraProvider here mirrors what a host app provides; the embedded
// Inspector does not bring its own provider, but Toaster needs one to render.
const renderEmbeddedInspector = (props: Partial<Parameters<typeof Inspector>[0]> = {}) =>
  render(
    <ChakraProvider value={defaultSystem}>
      <Inspector projectUrl="http://localhost:5005" botDataEndpoint="/data" {...props} />
    </ChakraProvider>,
  );

describe("Inspector (embedded)", () => {
  beforeEach(() => {
    vi.clearAllMocks();
    initInspectorStore();
  });

  it("renders TryAssistant", () => {
    renderEmbeddedInspector();

    expect(screen.getByTestId("try-assistant")).toBeInTheDocument();
  });

  it("uses generated uuid when projectId is not provided", () => {
    renderEmbeddedInspector();

    expect(mockUseBotConnection).toHaveBeenCalledWith(
      expect.objectContaining({ projectId: "generated-uuid" }),
    );
  });

  it("uses provided projectId instead of generated uuid", () => {
    renderEmbeddedInspector({ projectId: "custom-project-id" });

    expect(mockUseBotConnection).toHaveBeenCalledWith(
      expect.objectContaining({ projectId: "custom-project-id" }),
    );
  });

  it("passes singleSessionMode as useMemoryOnly to useBotConnection", () => {
    renderEmbeddedInspector({ singleSessionMode: true });

    expect(mockUseBotConnection).toHaveBeenCalledWith(
      expect.objectContaining({ useMemoryOnly: true }),
    );
  });

  it("defaults useMemoryOnly to false when singleSessionMode is not set", () => {
    renderEmbeddedInspector();

    expect(mockUseBotConnection).toHaveBeenCalledWith(
      expect.objectContaining({ useMemoryOnly: false }),
    );
  });

  it("initializes store with inspectMode=true when initialInspectMode is true", () => {
    renderEmbeddedInspector({ initialInspectMode: true });

    expect(screen.getByTestId("try-assistant")).toBeInTheDocument();
  });

  it("forwards onSessionStart callback to useBotConnection", () => {
    const onSessionStart = vi.fn();
    renderEmbeddedInspector({ onSessionStart });

    expect(mockUseBotConnection).toHaveBeenCalledWith(expect.objectContaining({ onSessionStart }));
  });

  it("forwards onReconnectError callback to useBotConnection", () => {
    const onReconnectError = vi.fn();
    renderEmbeddedInspector({ onReconnectError });

    expect(mockUseBotConnection).toHaveBeenCalledWith(
      expect.objectContaining({ onReconnectError }),
    );
  });

  it("forwards onMessageSent callback to useBotConnection", () => {
    const onMessageSent = vi.fn();
    renderEmbeddedInspector({ onMessageSent });

    expect(mockUseBotConnection).toHaveBeenCalledWith(expect.objectContaining({ onMessageSent }));
  });

  it("initializes store with isEmbedded=true", () => {
    renderEmbeddedInspector();

    expect(inspectorStore.state.isEmbedded).toBe(true);
  });

  it("initializes store with authToken when provided", () => {
    renderEmbeddedInspector({ authToken: "my-secret-token" });

    expect(inspectorStore.state.authToken).toBe("my-secret-token");
  });

  it("syncs authToken to store when the prop changes after mount", () => {
    const { rerender } = renderEmbeddedInspector({ authToken: "token-A" });

    expect(inspectorStore.state.authToken).toBe("token-A");

    rerender(
      <ChakraProvider value={defaultSystem}>
        <Inspector projectUrl="http://localhost:5005" botDataEndpoint="/data" authToken="token-B" />
      </ChakraProvider>,
    );

    expect(inspectorStore.state.authToken).toBe("token-B");
  });

  it("clears authToken in store when the prop becomes undefined", () => {
    const { rerender } = renderEmbeddedInspector({ authToken: "token-A" });

    expect(inspectorStore.state.authToken).toBe("token-A");

    rerender(
      <ChakraProvider value={defaultSystem}>
        <Inspector projectUrl="http://localhost:5005" botDataEndpoint="/data" />
      </ChakraProvider>,
    );

    expect(inspectorStore.state.authToken).toBeUndefined();
  });

  describe("channel routing", () => {
    it("enables useBotConnection and disables useTrackerConnection when no channel is provided", () => {
      renderEmbeddedInspector();

      expect(mockUseBotConnection).toHaveBeenCalledWith(expect.objectContaining({ enabled: true }));
      expect(mockUseTrackerConnection).toHaveBeenCalledWith(
        expect.objectContaining({ enabled: false, channel: "" }),
      );
    });

    it("enables useTrackerConnection and disables useBotConnection when a non-inspector channel is provided", () => {
      renderEmbeddedInspector({ channel: "rest" });

      expect(mockUseTrackerConnection).toHaveBeenCalledWith(
        expect.objectContaining({ enabled: true, channel: "rest" }),
      );
      expect(mockUseBotConnection).toHaveBeenCalledWith(
        expect.objectContaining({ enabled: false }),
      );
    });

    it("treats channel=inspector the same as no channel (uses useBotConnection)", () => {
      renderEmbeddedInspector({ channel: "inspector" });

      expect(mockUseBotConnection).toHaveBeenCalledWith(expect.objectContaining({ enabled: true }));
      expect(mockUseTrackerConnection).toHaveBeenCalledWith(
        expect.objectContaining({ enabled: false, channel: "inspector" }),
      );
    });
  });
});
